-- Minimal copy of the content tables for local dry runs of content batches (see docs/content-handoff.md).
create table subjects (id uuid primary key default gen_random_uuid(), name text unique, exam_board text, spec_code text);
create table topics (id uuid primary key default gen_random_uuid(), subject_id uuid references subjects(id), name text not null, spec_ref text, paper text, display_order int, created_at timestamptz default now());
create table subtopics (id uuid primary key default gen_random_uuid(), topic_id uuid references topics(id), name text not null, spec_ref text, display_order int, created_at timestamptz default now());
create table questions (id uuid primary key default gen_random_uuid(), subtopic_id uuid references subtopics(id) on delete cascade, topic_id uuid references topics(id) on delete cascade, question_text text not null, option_a text not null, option_b text not null, option_c text not null, option_d text not null, correct_option char(1) not null check (correct_option in ('A','B','C','D')), explanation text, difficulty text not null check (difficulty in ('foundation','higher')), question_type text not null check (question_type in ('recall','applied','calculation')), ao_weighting text check (ao_weighting in ('AO1','AO2','AO3')), generation_batch_id uuid, content_hash text, active boolean default true, created_at timestamptz default now());
create table quizzes (id uuid primary key default gen_random_uuid(), topic_id uuid references topics(id), title text not null, display_order int not null, question_count int not null default 0, cooldown_hours int not null default 168, created_at timestamptz default now());
create table quiz_questions (quiz_id uuid references quizzes(id) on delete cascade, question_id uuid references questions(id) on delete cascade, position int not null, primary key (quiz_id, question_id));
